import type {DashboardState} from './types.ts';

/** Source/evidence-backed data only: unknown balances never create a card.
 * Numeric or string zero is a legitimate reconciled balance and remains visible.
 * No fake local demo values are generated by this helper.
 */
export function hasFinancialEvidence(state:DashboardState|null):boolean {
  if(!state)return false;
  const accounting=state.accounting;
  return state.wallet.balances.length>0 ||
    [accounting.available,accounting.grossProceeds,accounting.financingFees,
     accounting.swapCosts,accounting.gasFees,accounting.cumulativeNetPnl,
     accounting.realizedProfit,accounting.realizedLoss].some(value=>value!==null&&value!==undefined);
}
